import {projectTimeline,renderTimelineEventBody} from '../../shared/timeline-presentation.js';
import {projectArtistPublic,publicGroupNavigation} from '../../shared/public-projection.js';
import {artist} from './data.js';
export {artist};
import {reconciliationView} from './reconciled-view.js';
import {relationView,publicTimeline} from '../../release-navigation.mjs';
export function render(context){return renderArtist(artist,context);}
/** Pure rendering entry also used for full-model/projection equivalence tests. */
export function renderArtist(source,{route,helpers:baseHelpers}) {
 const artist=projectArtistPublic(source);
 const pageMediaContext=route.page==='home'?'feature':route.page==='work'?'detail':'card';
 const videoSources=new Set(artist.works.filter(work=>['mv','stage'].includes(work.type)&&work.image).map(work=>typeof work.image==='string'?work.image:work.image.src??work.image.path??work.image.url));
 const h={...baseHelpers,image(asset,alt,options={}){
  const source=typeof asset==='string'?asset:asset?.src??asset?.path??asset?.url;
  return baseHelpers.image(asset,alt,{context:pageMediaContext,...options,...(videoSources.has(source)?{mediaRole:'video-preview',fit:'contain'}:{})});
 }};
const e=h.escape,k=h.entityKey,to=(page,key=null,q=route.query)=>h.href(artist.slug,page,key,q);
const view=reconciliationView(artist,h,'cb');
const relations=relationView(artist,h,route,'cb');
const clearFilters=()=>{const q=new URLSearchParams(route.query);q.delete('q');q.delete('type');return to('works',null,q);};
const portrait=m=>m.image?h.image(m.image,m.nameZh+' '+m.name,{fit:'contain',position:'50% 50%'}):`<div class="cb-initial">${e(m.name)}</div>`;
const name=(m,i)=>`<div class="cb-person-tile" data-media-tile><a class="cb-person-row" data-portrait-member="${e(k(m))}" href="${to('member',k(m))}"><span class="cb-person-number">${String(i+1).padStart(2,'0')}</span><div class="cb-person-portrait">${portrait(m)}</div><div class="cb-person-caption"><h3>${e(m.nameZh)}</h3><p>${e(m.name)}</p>${m.historical?'<small>历史成员</small>':''}</div><span aria-hidden="true">↗</span></a></div>`;
const record=(w,i)=>`<div class="cb-record-tile" data-media-tile><a class="cb-record-row" href="${to('work',k(w))}"><span class="cb-record-no">${String(i+1).padStart(2,'0')}</span><div class="cb-record-cover">${w.image?h.image(w.image,w.title+' '+({release:'发行封面',mv:'MV预览',stage:'舞台预览'})[w.type],{fit:'contain'}):`<span>${w.type==='release'?'发行封面暂缺':w.type==='mv'?'MV预览暂缺':'舞台预览暂缺'}</span>`}</div><div class="cb-record-copy"><small>${e(({release:'发行',mv:'MV',stage:'舞台'})[w.type])}</small><h3>${e(w.title)}</h3>${w.version?`<p>${e(w.version)}</p>`:''}</div><time>${e(h.dateLabel(w.date,w.precision))}</time><span class="cb-record-arrow" aria-hidden="true">↗</span></a></div>`;
const heading=(text,sub='')=>`<div class="cb-page-heading"><h1>${e(text)}</h1>${sub?`<p>${e(sub)}</p>`:''}</div>`;
const nav=`<aside class="cb-spine"><a class="cb-monogram" href="${to('home')}" aria-label="Cherry Bullet 首页">CB</a><nav aria-label="团体导航">${[['home','首页'],['members','成员'],['works','作品'],['timeline','时间轴']].map(([p,n])=>`<a href="${to(p)}" ${(route.page==='member'?'members':route.page==='work'?'works':route.page)===p?'aria-current="page"':''}>${n}</a>`).join('')}</nav><span class="cb-spine-end" aria-hidden="true">Cherry<br>Bullet</span></aside>`;
let content='';
if(route.page==='home')content=`<header class="cb-cover-heading"><div><p class="cb-eyebrow">Cherry Bullet</p><h1>Cherry Bullet</h1></div><p data-public-group-navigation="cherrybullet">${e(publicGroupNavigation('cherrybullet'))}</p></header><section class="cb-cover-spread" aria-labelledby="cb-photo-period"><div class="cb-photo-label"><h2 id="cb-photo-period">Cherry Dash</h2><p>2023 · 七人时期团体照</p></div><figure class="cb-cover-photo">${h.image(artist.hero,'Cherry Bullet 2023《Cherry Dash》七人时期官方概念照',{loading:'eager',fit:'contain',caption:true})}</figure><p class="cb-photo-note">团体照记录此时的七人阵容；下方另列十位历史成员。</p></section><section class="cb-cover-members" aria-labelledby="cb-member-history"><div class="cb-section-title"><div><p class="cb-eyebrow">人物</p><h2 id="cb-member-history">十位历史成员</h2><p class="cb-section-note">2019 官方个人资料照 · 中文名与原文名分别列示</p></div><a href="${to('members')}">成员目录 ↗</a></div><div class="cb-cover-name-index">${artist.members.map(name).join('')}</div></section><section class="cb-record-section"><div class="cb-section-title"><div><p class="cb-eyebrow">发行</p><h2>唱片目录</h2></div><a href="${to('works',null,{type:'release'})}">全部发行 ↗</a></div><div class="cb-record-shelf">${artist.works.filter(w=>w.type==='release').slice(0,4).map((w,i)=>`<div class="cb-release-tile" data-media-tile><a href="${to('work',k(w))}">${w.image?h.image(w.image,w.title+' 正式发行封面',{fit:'contain'}):''}<p class="cb-shelf-year">${e(h.dateLabel(w.date,w.precision))}</p><h3>${e(w.title)}</h3></a></div>`).join('')}</div></section><section class="cb-film-section"><div class="cb-section-title"><div><p class="cb-eyebrow">影像</p><h2>MV 与舞台</h2></div><a href="${to('works',null,{type:'mv'})}">MV 目录 ↗</a></div><div class="cb-film-index">${artist.works.filter(w=>w.type==='mv').slice(0,3).map(record).join('')}</div></section><a class="cb-time-door" href="${to('timeline')}"><div><p class="cb-eyebrow">日期与作品</p><h2>阅读时间轴</h2></div><span>从最早到最新 ↗</span></a>`;
else if(route.page==='members'){const query=(route.query.get('q')||'').normalize('NFKC').toLowerCase(),rows=artist.members.filter(m=>[m.name,m.nameZh].some(v=>v.normalize('NFKC').toLowerCase().includes(query)));content=heading('成员目录','十位历史成员 · 2019 官方个人资料照；成员经历按不同时期分别列示。')+`<form class="cb-search" data-member-search><label>搜索成员<input name="q" type="search" value="${e(route.query.get('q')||'')}" placeholder="中文名或原文名"></label><button>查找</button></form><div class="cb-member-index">${rows.map(name).join('')}</div>${!rows.length?`<p>没有找到匹配的成员。</p><a href="${to('members',null,{})}">清除筛选</a>`:''}`;}
else if(route.page==='member'){
const m=artist.members.find(x=>k(x)===route.key);content=m?`<a class="cb-back" href="${to('members')}">← 返回成员目录</a><article class="cb-member-page" data-member-id="${e(m.id)}"><div class="cb-member-title"><p>${e(m.name)}</p><h1>${e(m.nameZh)}</h1>${m.historical?'<span>历史成员</span>':''}</div><div class="cb-member-photo">${portrait(m)}</div><div class="cb-member-prose"><p>${e(view.profile(m))}</p>${view.career(m)}${view.sources(m.sources)}${relations.member(m)}<a class="cb-link" href="${to('works')}">团体作品目录 ↗</a></div></article>`:heading('没有找到这位成员')+`<a href="${to('members')}">返回成员目录</a>`;
}else if(route.page==='works'){
const q=route.query.get('q')||'',type=route.query.get('type')||'all',rows=h.filterWorks(artist.works,{query:q,type});content=heading('作品目录','正式发行、MV 与具体舞台分别浏览，版本与日期保留各自口径。')+`<form class="cb-search" data-work-search><label>搜索作品<input name="q" value="${e(q)}" placeholder="作品名称"></label><label>作品类型<select name="type">${[['all','全部'],['release','发行'],['mv','MV'],['stage','舞台']].map(([v,n])=>`<option value="${v}" ${v===type?'selected':''}>${n}</option>`).join('')}</select></label><button>查找</button></form><p class="cb-result" aria-live="polite">${rows.length} 件作品</p><div class="cb-library">${rows.map(record).join('')}</div>${!rows.length?`<p>没有找到匹配的作品。</p><a class="cb-link" href="${clearFilters()}">清除筛选 ↗</a>`:''}`;
}else if(route.page==='work'){
const w=artist.works.find(x=>k(x)===route.key);content=w?`<a class="cb-back" href="${to('works')}">← 返回作品目录</a><article class="cb-work-page" data-work-key="${e(k(w))}" data-has-media="${Boolean(w.image)}"><div class="cb-work-type">${e(({release:'发行',mv:'MV',stage:'舞台'})[w.type])}</div><h1>${e(w.title)}</h1><div class="cb-work-image" data-review-media-column>${w.image?h.image(w.image,w.title+' '+({release:'正式发行封面',mv:'MV预览',stage:'舞台预览'})[w.type],{fit:'contain',caption:true}):`<div class="cb-mv-type">${e(w.type==='release'?'发行封面暂缺':w.type==='mv'?'MV预览暂缺':'舞台预览暂缺')}</div>`}</div><div class="cb-work-notes" data-review-facts-column><time>${e(h.dateLabel(w.date,w.precision))}</time><p>${e(w.dateKind==='music_release'?'音乐发行日期':w.dateKind||'')}</p>${w.version?`<p>${e(w.version)}</p>`:''}${h.sources(w.sources)}${relations.detail(w)}${w.videoId?`<a class="cb-link" href="${e(h.videoHref(w.videoId))}" target="_blank" rel="noopener">前往官方视频 ↗</a>`:''}</div></article>`:heading('没有找到这件作品')+`<a href="${to('works')}">返回作品目录</a>`;
}else if(route.page==='timeline'){
 content=heading('时间轴')+`<ol class="cb-timeline" data-timeline>${publicTimeline(artist).map(v=>`<li data-event-id="${e(v.id)}" tabindex="-1">${v.mainDate?`<time datetime="${e(v.mainDate)}">${e(h.dateLabel(v.mainDate,v.precision))}${v.mainLabel?`<small class="timeline-main-kind"> · ${e(v.mainLabel)}</small>`:''}</time>`:''}<div>${renderTimelineEventBody(v,h,{summaryClass:'cb-event-summary',datesClass:'cb-event-dates',sourcesClass:'cb-sources'})}${relations.event(v)}</div></li>`).join('')}</ol>`;
 }
return`<div class="cb-shell">${nav}<div class="cb-leaf"><main class="cb-main">${content}</main><footer class="cb-footer"><a href="${to('home')}">Cherry Bullet</a><a href="${to('home')}">回到首页 ↑</a></footer></div></div>`;
}
export function afterRender({root,route,helpers:h}){const f=root.querySelector('[data-work-search],[data-member-search]');if(!f)return;const cb=event=>{event.preventDefault();const d=new FormData(f),q=new URLSearchParams(route.query);for(const [name,value]of d)q.set(name,String(value));h.navigate(h.href(artist.slug,route.page==='members'?'members':'works',null,q));};f.addEventListener('submit',cb);return()=>f.removeEventListener('submit',cb);}

// Presentation adapters only. Reconciled source fields and review decisions remain unchanged.
export function reconciliationView(artist,h,prefix){
 const e=h.escape;
 const heldURLs=new Set(artist.heldSourceUrls||[]);
 const stamp=d=>d?.value?h.dateLabel(d.value,d.precision):'';
 const sources=(rows=[],label='资料来源')=>{
  const list=rows.map(s=>typeof s==='string'?{url:s,title:'来源'}:s).filter(s=>/^https?:\/\//i.test(s?.url||'')&&!heldURLs.has(s.url));
  return list.length?`<details class="${prefix}-source-notes"><summary>${e(label)}</summary><ul>${list.map(s=>`<li><a href="${e(s.url)}" target="_blank" rel="noopener noreferrer">${e((s.title||s.label||'来源').replace(/^资料说明[：:]\s*/,''))}</a>${s.publisher?`<span>${e(s.publisher)}</span>`:''}${stamp(s.sourcePublishedAt)?`<p>原刊发布：<time datetime="${e(s.sourcePublishedAt.value)}">${e(stamp(s.sourcePublishedAt))}</time></p>`:''}</li>`).join('')}</ul></details>`:'';
 };
 const dateRow=(label,value,precision)=>value&&h.dateLabel(value,precision)?`<div><dt>${e(label)}</dt><dd><time datetime="${e(value)}">${e(h.dateLabel(value,precision))}</time></dd></div>`:'';
 const profile=m=>{
  return m.displayProfile??m.profile??'';
 };
 const career=m=>{
  const periods=m.careerPeriods||[],rows=m.careerSources||[];
  return `<section class="${prefix}-career"><h2>成员资料与经历</h2>${m.role?`<p>${e(m.role)}</p>`:''}<p>${m.historical?'历史成员':'公开资料中的成员关系'}</p>${periods.map(p=>{
   const ps=rows.filter(s=>(p.sourceIds||[]).includes(s.sourceId||s.id));
   return `<article data-period-id="${e(p.periodId)}"><h3>${e(p.displayName||artist.name)}</h3><p>${p.relationType==='roster_listing'?'官方资料列示':'团体参与经历'}</p><dl>${dateRow(p.startDateBasis==='public_debut'?'团体公开出道':'资料记述起点',p.startDate,p.startPrecision)}${dateRow('资料记述结束',p.endDate,p.endPrecision)}${dateRow('相关公告',p.announcedDate?.value,p.announcedDate?.precision)}${dateRow('资料记述生效',p.effectiveDate?.value,p.effectiveDate?.precision)}</dl>${(p.events||[]).map(v=>`<p>${e(v.label||'')}${v.date?` <time datetime="${e(v.date)}">${e(h.dateLabel(v.date,v.precision))}</time>`:''}</p>`).join('')}${sources(ps,'经历来源')}</article>`;
  }).join('')}${sources(m.officialUrl?[{url:m.officialUrl,title:'个人资料原始来源'}]:[],'个人资料来源')}</section>`;
 };
 const event=t=>{
  const raw=t.canonicalEvent||t,states={announced:'公告',planned:'计划',postponed:'延期公告',cancelled:'取消公告'},types={debut:'出道',release:'发行',member_departure:'成员',contract_end:'合约',notice:'平台公告',other:'活动'};
  const main=raw.eventDate||raw.announcementDate;
  const dates=[['事项日期',raw.eventDate],['公告日期',raw.announcementDate],['计划日期',raw.plannedDate],['生效日期',raw.effectiveDate]].filter(([,d])=>stamp(d));
  const summary=(raw.publicSummary??raw.summary??'').replace(/同日专辑与主打合并为一次发行事件。?/g,'');
  const related=(raw.workIds||[]).filter(id=>artist.works.some(w=>w.id===id));
  return {id:raw.id,title:raw.title,summary,state:states[raw.status]||types[raw.eventType]||'事项',mainDate:main?.value||null,precision:main?.precision||null,dates:dates.length?`<dl class="${prefix}-event-dates">${dates.map(([label,d])=>dateRow(label,d.value,d.precision)).join('')}</dl>`:'',related,sources:sources(raw.sources||[],'事件来源')};
 };
 return {profile,career,event,sources};
}

